INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-474','game3','Your neighbour accidentally locks themselves out of their house in their pyjamas and asks for help. You would...','tell everyone|chase them away|break into their house','Morality');
