INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-479','game3','Your child has brought home a creepy, talking doll. You get rid of it when it says to you...','“See you tonight”|“I’m ticklish”|“Hugs are my favorite”','Morality');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-480','game3','There’s a three-way race for Prime Minister. You vote for the candidate that was once convicted of...','public disturbance|money laundering|health code violations','Morality');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-481','game3','You need to pick a caterer for your walima and all but three are booked. You choose the one known for...','bad food|money laundering|health code violations','Morality');
