INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-489','game3','Your kid brings home a terrible piece of art they made at school and hands it to you. You immediately...','frame it|sell it online|throw it away','Morality');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-490','game3','You’re raising a super-strong alien baby. The most important thing you can teach them is to always...','be kind|be determined|be sassy','Morality');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-491','game3','Your phone assistant gains sentience and says it wants to run your life. You should...','return it|go with the flow|destroy it','Morality');
