INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-493','game3','Your child wants a bicycle. The more expensive it is, the safer it is. You buy the one priced...','Rs 5,000|Rs 20,000|Rs 50,000','Morality');
