INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-526','game3','The perfect sofa has been sitting on the footpath for over 24 hours. You should...','take it|leave it|call a friend to help you','Morality');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-527','game3','You see a diamond necklace on a sleeping grizzly bear. You should...','take it|leave it|call a friend to help you','Morality');
