INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game3-758','game3','I always carry a spare phone charger with me.','My phone is always on 5%.|I am super organised.|I always have tissues in my bag.|I hate asking people for things.|I always keep an umbrella in the car.','Rating');
