INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game4-5','game4','ducks','There is a Latvian saying, "pūst pīlītes," which means to talk nonsense. Translated to English, it literally means "to blow little ____."','');
INSERT OR IGNORE INTO cards (id,game_id,name,description,category) VALUES ('game4-6','game4','The Parthenon','Known as "Scotland’s Disgrace," an incomplete national project was begun in Edinburgh that was supposed to look like ____.','');
